use dioxus::prelude::*;
use x2bib::{BibLaTeX, BibReturn, PlainBibLaTeX};

use super::main::{Error, Props, Success};

/// Citation file names searched for inside a package's source repository.
const CITATION_FILENAMES: [&str; 3] = ["CITATION.cff", "CITATION.bib", "citation.bib"];

/// A source from which a BibLaTeX entry can be generated.
///
/// Every source is simply one variant of this enum and all of them are treated equally: the
/// dropdown and the help section are generated by iterating over [`Source::ALL`] and the form
/// dispatches through the single match in [`Source::run`]. Adding a new source therefore only
/// requires a new variant and filling in the matching arms below.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Source {
    /// A crate hosted on [crates.io](https://crates.io).
    Crate,
    /// A package hosted on [PyPI](https://pypi.org).
    PyPI,
    /// A package registered in the Julia General registry.
    Julia,
    /// A [DOI](https://www.doi.org/).
    Doi,
    /// An item hosted on [archive.org](https://archive.org).
    ArchiveOrg,
    /// A book identified by its [ISBN](https://en.wikipedia.org/wiki/ISBN).
    Isbn,
}

impl Source {
    /// All sources known to the app, in the order they are presented to the user.
    pub const ALL: [Source; 6] = [
        Source::Crate,
        Source::PyPI,
        Source::Julia,
        Source::Doi,
        Source::ArchiveOrg,
        Source::Isbn,
    ];

    /// Identifier used both as the form value and as the label shown in the dropdown.
    pub fn id(self) -> &'static str {
        match self {
            Source::Crate => "crate",
            Source::PyPI => "PyPI",
            Source::Julia => "Julia",
            Source::Doi => "DOI",
            Source::ArchiveOrg => "archive.org",
            Source::Isbn => "ISBN",
        }
    }

    /// Resolves a [Source] from its [`Source::id`].
    pub fn from_id(id: &str) -> Option<Source> {
        Source::ALL.into_iter().find(|s| s.id() == id)
    }

    /// A short help paragraph describing this source.
    pub fn description(self) -> Element {
        match self {
            Source::Crate => rsx! {
                p {
                    "Crates are resolved on "
                    a { href: "https://crates.io/", "crates.io" }
                    " and their repository is scanned for "
                    code { "CITATION.cff" }
                    " files. A specific version can be requested with "
                    code { "crate@version" }
                    "."
                }
            },
            Source::PyPI => rsx! {
                p {
                    "Python packages are looked up on "
                    a { href: "https://pypi.org/", "PyPI" }
                    ". A specific version can be requested with "
                    code { "package@version" }
                    "."
                }
            },
            Source::Julia => rsx! {
                p {
                    "Julia packages are looked up in the "
                    a { href: "https://github.com/JuliaRegistries/General", "General registry" }
                    ". A specific version can be requested with "
                    code { "package@version" }
                    "."
                }
            },
            Source::Doi => rsx! {
                p {
                    "BibTeX entries for DOIs are obtained directly from "
                    a { href: "https://doi.org/", "doi.org" }
                    "."
                }
            },
            Source::ArchiveOrg => rsx! {
                p {
                    "Books, articles and other items can be generated from an "
                    a { href: "https://archive.org/", "archive.org" }
                    " details URL or identifier."
                }
            },
            Source::Isbn => rsx! {
                p {
                    "Books can be cited by their ISBN, resolved via "
                    a { href: "https://openlibrary.org/", "Open Library" }
                    " (with a "
                    a { href: "https://books.google.com/", "Google Books" }
                    " fallback)."
                }
            },
        }
    }

    /// Runs the lookup for `input` and returns the resulting message elements (newest first).
    pub async fn run(self, input: &str) -> Vec<Element> {
        match self {
            Source::Crate => {
                let (name, version) = parse_name_version(input);
                package_messages(
                    x2bib::get_biblatex(name, version, None, None, CITATION_FILENAMES.to_vec())
                        .await,
                    name,
                )
            }
            Source::PyPI => {
                let (name, version) = parse_name_version(input);
                package_messages(
                    x2bib::get_biblatex_pypi(
                        name,
                        version,
                        None,
                        None,
                        CITATION_FILENAMES.to_vec(),
                    )
                    .await,
                    name,
                )
            }
            Source::Julia => {
                let (name, version) = parse_name_version(input);
                package_messages(
                    x2bib::get_biblatex_julia(
                        name,
                        version,
                        None,
                        None,
                        CITATION_FILENAMES.to_vec(),
                    )
                    .await,
                    name,
                )
            }
            Source::Doi => vec![doi_message(input).await],
            Source::ArchiveOrg => vec![archive_org_message(input).await],
            Source::Isbn => vec![isbn_message(input).await],
        }
    }
}

/// Splits an `input` of the form `name@version` into its name and optional version.
fn parse_name_version(input: &str) -> (&str, Option<&str>) {
    match input.split_once('@') {
        Some((name, version)) => {
            let version = version.trim();
            (name.trim(), (!version.is_empty()).then_some(version))
        }
        None => (input.trim(), None),
    }
}

/// Builds a success/error message element.
fn error(e: impl std::fmt::Display) -> Element {
    Error(Props {
        message: rsx! { "ERROR: {e}" },
    })
}

/// Converts the result of a package lookup (which may yield multiple candidate entries) into the
/// message elements to display, newest first.
fn package_messages(results: x2bib::Result<Vec<x2bib::Result<BibLaTeX>>>, name: &str) -> Vec<Element> {
    match results {
        Ok(entries) => entries
            .into_iter()
            .rev()
            .map(|entry| match entry {
                Ok(entry) => convert_entry(entry, name),
                Err(e) => error(e),
            })
            .collect(),
        Err(e) => vec![error(e)],
    }
}

/// Turns a single [BibLaTeX] entry into a success message element.
fn convert_entry(entry: BibLaTeX, name: &str) -> Element {
    let (source_name, link, found_message) = match entry {
        BibLaTeX::CratesIO(ref e) => (
            "crates.io".to_string(),
            format!("https://crates.io/crates/{name}"),
            match &e.version {
                Some(v) => format!("{name} {v}"),
                None => name.to_string(),
            },
        ),
        BibLaTeX::PyPI(ref e) => (
            "PyPI".to_string(),
            e.url
                .clone()
                .unwrap_or_else(|| format!("https://pypi.org/project/{name}/")),
            format!("{name} {}", e.version),
        ),
        BibLaTeX::Julia(ref e) => (
            "Julia".to_string(),
            e.url
                .clone()
                .unwrap_or_else(|| format!("https://juliahub.com/ui/Packages/General/{name}")),
            format!("{name} {}", e.version),
        ),
        BibLaTeX::CITATIONCFF(ref e) => (
            "CITATION.cff".to_string(),
            e.url.clone().map_or("".to_string(), |x| format!("{x}")),
            match &e.version {
                Some(v) => format!("{name} {v}"),
                None => name.to_string(),
            },
        ),
        #[allow(unused)]
        BibLaTeX::Plain(PlainBibLaTeX {
            ref bibliography,
            ref repository,
            ref filename,
        }) => (
            "bibliography file".to_string(),
            repository.clone(),
            name.to_string(),
        ),
    };
    Success(Props {
        message: rsx! {
            p {
                "Found entry for "
                code { "{found_message}" }
                " from "
                a { href: link, {source_name} }
            }
            textarea { class: "response", readonly: true, "{entry}" }
        },
    })
}

/// Generates the message element for a DOI lookup.
async fn doi_message(doi: &str) -> Element {
    match x2bib::get_bibtex_doi_without_client(doi, None).await {
        Ok(bib) => {
            let bib_output = match bib {
                BibReturn::BibFile(bib) => bib.to_biblatex_string(),
                BibReturn::String(s) => s,
            }
            .split_once("\n")
            .map(|(first, rest)| format!("{}\n{rest}", first.replace("_", "")))
            .unwrap_or_default()
            .replace(",\n", ",\n    ")
            .replace(",\n    }", ",\n}")
            .trim_end()
            .to_string();
            Success(Props {
                message: rsx! {
                    p {
                        "Found DOI "
                        a { href: "https://doi.org/{doi}", code { "{doi}" } }
                    }
                    textarea { class: "response", readonly: true, "{bib_output}" }
                },
            })
        }
        Err(e) => error(e),
    }
}

/// Generates the message element for an archive.org lookup.
async fn archive_org_message(input: &str) -> Element {
    match x2bib::generate_biblatex_archive_org_without_client(input, None).await {
        Ok(entry) => {
            let url = entry.url.clone();
            Success(Props {
                message: rsx! {
                    p {
                        "Found archive.org item "
                        a { href: "{url}", code { "{entry.identifier}" } }
                    }
                    textarea { class: "response", readonly: true, "{entry}" }
                },
            })
        }
        Err(e) => error(e),
    }
}

/// Generates the message element for an ISBN lookup.
async fn isbn_message(input: &str) -> Element {
    match x2bib::generate_biblatex_isbn_without_client(input, None).await {
        Ok(entry) => {
            let isbn = entry.isbn.clone();
            Success(Props {
                message: rsx! {
                    p {
                        "Found book with ISBN "
                        code { "{isbn}" }
                    }
                    textarea { class: "response", readonly: true, "{entry}" }
                },
            })
        }
        Err(e) => error(e),
    }
}
